  const visible=useMemo(()=>templates.filter(item=>(type==="all"||(item.application_type||item.applicationType||item.definition.applicationType)===type)&&(!query.trim()||`${item.name} ${item.code} ${item.definition.description||""}`.toLowerCase().includes(query.trim().toLowerCase()))),[templates,type,query]);
