  if(editor)return <TemplateEditor value={initial as Template} saving={saving} onClose={()=>setEditor(null)} onSave={async value=>{setSaving(true);setNotice("");try{const definition={...value.definition,steps:value.definition.steps.map(step=>{const clean={...step};delete clean.documentAction;delete clean.documentRequired;return clean})};await fetch("/api/workflows/templates",{method:value.id?"PATCH":"POST",headers:{"content-type":"application/json"},body:JSON.stringify({...value,definition,...definition})}).then(json);setEditor(null);setNotice("Workflow 템플릿을 새 버전으로 저장했습니다.");load()}catch(reason){setNotice(reason instanceof Error?reason.message:"저장하지 못했습니다.")}finally{setSaving(false)}}}/>;
  return <section className="wv2-module wv2-workflow-module"><header className="wv2-module-head"><div><small>WORKFLOW TEMPLATE</small><h1>워크플로우 템플릿</h1><p>전사 공통 단계·Role·필수조건을 버전으로 관리합니다.</p></div><button className="primary" onClick={()=>setEditor("new")}><Plus size={18}/>새 템플릿</button></header><div className="wv2-module-toolbar"><label><Search size={18}/><input value={query} onChange={event=>setQuery(event.target.value)} placeholder="템플릿명·코드·설명 검색"/></label><button className={type!=="all"?"active":""}><Filter size={18}/>유형</button><select value={type} onChange={event=>setType(event.target.value)}><option value="all">전체 유형</option>{Object.entries(applicationLabels).map(([value,label])=><option key={value} value={value}>{label}</option>)}</select><span>{visible.length}개 템플릿</span></div>{notice&&<p className="wv2-workflow-notice">{notice}</p>}{loading?<Empty title="템플릿을 불러오는 중…" icon={RefreshCw}/>:visible.length?<div className="wv2-workflow-template-grid">{visible.map(item=><button key={item.id} onClick={()=>setEditor(item)}><header><span>{applicationLabels[item.application_type||item.applicationType||item.definition.applicationType||"GENERAL"]}</span><em className={item.status}>{item.status==="active"?"사용 중":"사용 중지"}</em></header><h2>{item.name}</h2><p>{item.definition.description||"설명이 없습니다."}</p><footer><span>v{item.current_version||item.currentVersion||1}</span><span>{item.definition.steps?.length||0}단계</span><span>{item.definition.registerCommonDocument?"공식문서 등록":"일반 처리"}</span><ChevronRight size={18}/></footer></button>)}</div>:<Empty title="조건에 맞는 템플릿이 없습니다." icon={Workflow}/>}</section>;
