function TemplateEditor({value,saving,onClose,onSave}:{value:Template;saving:boolean;onClose:()=>void;onSave:(value:Template)=>void}){
  const [form,setForm]=useState<Template>(()=>structuredClone(value));
  const [projectRoles,setProjectRoles]=useState<ProjectRoleOption[]>([]);
  const [documentCategories,setDocumentCategories]=useState<DocumentCategoryOption[]>([]);
  const [masterNotice,setMasterNotice]=useState("");
  const steps=form.definition.steps||[];

  useEffect(()=>{
    const controller=new AbortController();
    fetch("/api/system/master-data",{cache:"no-store",signal:controller.signal}).then(json).then(data=>{
      setProjectRoles((data.projectRoles??[]).filter((item:ProjectRoleOption)=>item.enabled!==false&&item.enabled!==0));
      setDocumentCategories((data.codes??[]).filter((item:DocumentCategoryOption)=>item.groupCode==="DELIVERABLE_CATEGORY"&&item.enabled!==false&&item.enabled!==0));
    }).catch(reason=>{if(!(reason instanceof DOMException&&reason.name==="AbortError"))setMasterNotice("프로젝트 Role과 문서 카테고리를 불러오지 못했습니다.")});
    return()=>controller.abort();
  },[]);

  const patchStep=(index:number,patch:Partial<Step>)=>setForm(current=>({...current,definition:{...current.definition,steps:current.definition.steps.map((step,cursor)=>cursor===index?{...step,...patch}:step)}}));
  const move=(index:number,direction:number)=>{const next=index+direction;if(next<0||next>=steps.length)return;setForm(current=>{const list=[...current.definition.steps];[list[index],list[next]]=[list[next],list[index]];return {...current,definition:{...current.definition,steps:list}}})};
  const categoryValue=form.definition.documentCategory||"";
  const categoryExists=documentCategories.some(item=>item.code===categoryValue);

  return <section className="wv2-workflow-editor">
    <header>
      <div><small>{form.id?"EDIT WORKFLOW TEMPLATE":"NEW WORKFLOW TEMPLATE"}</small><h1>{form.id?form.name:"새 워크플로우 템플릿"}</h1><p>단계를 자유롭게 추가·삭제하고 같은 처리구분을 여러 번 사용할 수 있습니다.</p></div>
      <div className="wv2-workflow-editor-actions"><button onClick={onClose}>취소</button><button className="primary" disabled={saving||!form.name.trim()||!form.code.trim()} onClick={()=>onSave(form)}><Check size={18}/>{saving?"저장 중…":"새 버전 저장"}</button></div>
    </header>
    <main>
      {masterNotice&&<p className="wv2-workflow-error">{masterNotice}</p>}
      <section className="wv2-workflow-form">
        <div className="two"><label><span>템플릿명 *</span><input value={form.name} onChange={event=>setForm({...form,name:event.target.value})}/></label><label><span>템플릿 코드 *</span><input disabled={Boolean(form.id)} value={form.code} onChange={event=>setForm({...form,code:event.target.value.toUpperCase()})}/></label></div>
        <div className="three"><label><span>적용 유형</span><select value={form.definition.applicationType||"GENERAL"} onChange={event=>setForm({...form,definition:{...form.definition,applicationType:event.target.value}})}>{Object.entries(applicationLabels).map(([key,label])=><option key={key} value={key}>{label}</option>)}</select></label><label><span>Task 연결</span><select value={form.definition.taskLinkMode||"optional"} onChange={event=>setForm({...form,definition:{...form.definition,taskLinkMode:event.target.value}})}><option value="optional">선택</option><option value="required">필수</option><option value="disabled">사용 안 함</option></select></label><label><span>사용 여부</span><select value={form.status} onChange={event=>setForm({...form,status:event.target.value})}><option value="active">사용</option><option value="inactive">사용 중지</option></select></label></div>
        <label><span>설명</span><textarea rows={2} value={form.definition.description||""} onChange={event=>setForm({...form,definition:{...form.definition,description:event.target.value}})}/></label>
        <div className="wv2-workflow-document-rule"><label><input type="checkbox" checked={Boolean(form.definition.registerCommonDocument)} onChange={event=>setForm({...form,definition:{...form.definition,registerCommonDocument:event.target.checked}})}/>최종 승인 후 프로젝트 공통문서 등록</label>{form.definition.registerCommonDocument&&<select aria-label="최종 문서 카테고리" value={categoryValue} onChange={event=>setForm({...form,definition:{...form.definition,documentCategory:event.target.value}})}><option value="">문서 카테고리 선택</option>{categoryValue&&!categoryExists&&<option value={categoryValue}>{categoryValue} · 기존 설정</option>}{documentCategories.map(item=><option key={item.code} value={item.code}>{item.label}</option>)}</select>}</div>
      </section>
      <section className="wv2-workflow-step-editor">
        <header><div><h2>단계 설정</h2><span>{steps.length}단계 · 실행 시 현재 버전으로 고정</span></div><button onClick={()=>setForm(current=>({...current,definition:{...current.definition,steps:[...current.definition.steps,emptyStep()]}}))}><Plus size={18}/>단계 추가</button></header>
        <div className="head"><span>순서</span><span>단계명</span><span>처리구분</span><span>기본 Role</span><span>담당자 규칙</span><span>기한</span><span>필수조건</span><span>편집</span></div>
        {steps.map((step,index)=>{const roleExists=projectRoles.some(item=>item.code===step.roleCode);return <div className="row" key={`${index}-${step.name}`}><b>{index+1}</b><input value={step.name} onChange={event=>patchStep(index,{name:event.target.value})}/><select value={step.actionType} onChange={event=>patchStep(index,{actionType:event.target.value})}>{Object.entries(actionLabels).map(([key,label])=><option key={key} value={key}>{label}</option>)}</select><select value={step.roleCode||""} disabled={step.actionType==="WRITE"} onChange={event=>patchStep(index,{roleCode:event.target.value})}><option value="">Role 선택</option>{step.roleCode&&!roleExists&&<option value={step.roleCode}>{step.roleCode} · 기존 설정</option>}{projectRoles.map(item=><option key={item.code} value={item.code}>{item.name} · {item.code}</option>)}</select><select value={step.assignmentRule||"manual"} onChange={event=>patchStep(index,{assignmentRule:event.target.value})}><option value="requester">요청자</option><option value="project_pm">프로젝트 PM</option><option value="project_pl">프로젝트 PL</option><option value="task_role">Task 담당·Role</option><option value="project_role">프로젝트 Role</option><option value="manual">직접 지정</option></select><label className="days"><input type="number" min="0" value={step.dueDays||0} onChange={event=>patchStep(index,{dueDays:Number(event.target.value)})}/><span>일</span></label><span className="checks"><label><input type="checkbox" checked={Boolean(step.commentRequired)} onChange={event=>patchStep(index,{commentRequired:event.target.checked})}/>의견</label><label><input type="checkbox" checked={Boolean(step.attachmentRequired)} onChange={event=>patchStep(index,{attachmentRequired:event.target.checked})}/>첨부</label></span><span className="actions"><button onClick={()=>move(index,-1)} disabled={!index}><ArrowUp size={18}/></button><button onClick={()=>move(index,1)} disabled={index===steps.length-1}><ArrowDown size={18}/></button><button className="danger" onClick={()=>setForm(current=>({...current,definition:{...current.definition,steps:current.definition.steps.filter((_,cursor)=>cursor!==index)}}))} disabled={steps.length<=1}><Trash2 size={18}/></button></span></div>})}
      </section>
      <p className="wv2-workflow-version-note">진행 중 Workflow는 기존 버전을 유지합니다.</p>
    </main>
  </section>
}

